(() => {
    const g = __rhf.game;
    g.state.settings.autoQuality = false;
    g.setQuality('low');
    g.bears.directorT = 1e9;
    g.env.timeScale = 0;
    g.env.setTime(11);
    Object.assign(g.env.weather, { cloud: 0.3, cloudTarget: 0.3, rain: 0, rainTarget: 0, timer: 1e9 });
    g.hud.firstShown = -1000;
    g.hud.hint('', 0);
    __rhf.god(true);
    window.__until = async (fn, ms = 240000) => {
      const t0 = performance.now();
      while (performance.now() - t0 < ms) {
        const r = fn();
        if (r) return r;
        await new Promise((q) => setTimeout(q, 200));
      }
      return null;
    };
    g.state.money = 5000;
    g.screens.open('shop', { tab: 'garage' });
    return 'boat card ' + !!document.querySelector('[data-act="buy-boat"]');
  })()

(() => {
    const g = __rhf.game;
    const r = 'bought: owned ' + g.boat.owned + ', where ' + g.boat.where + ', money ' + g.state.money + ', motor card ' + !!document.querySelector('[data-act="buy-motor"]');
    g.screens.close();
    return r;
  })()

(() => {
    const g = __rhf.game;
    const W = g.world;
    const L = W.place('landing');
    let best = null;
    for (let i = 0; i < 72 && !best; i++) {
      const a = (i / 72) * Math.PI * 2;
      for (let r = 6; r < 80; r += 2) {
        const x = L.x + Math.sin(a) * r;
        const z = L.z + Math.cos(a) * r;
        const w = W.waterAt(x, z);
        if (!w || w.depth < 1.2) continue;
        // walk back inland from the deep water to dry flat ground
        for (let k = 8; k < 24; k += 1) {
          const cx = x - Math.sin(a) * k;
          const cz = z - Math.cos(a) * k;
          if (W.waterAt(cx, cz) || W.slopeAt(cx, cz) > 0.25 || g.colliders.circlesNear(cx, cz, 4).length) continue;
          best = { x: cx, z: cz, yaw: a + Math.PI, wx: x, wz: z };
          break;
        }
        break;
      }
    }
    if (!best) return 'no spot by the river';
    g.hotrod.place(best.x, best.z, best.yaw);
    g.hotrod.speed = 0;
    g.boat.resetTrailer();
    window.__spot = best;
    const ex = g.hotrod.exitPoint(1);
    g.player.place(ex.x + Math.sin(best.yaw) * 6, ex.z + Math.cos(best.yaw) * 6, best.yaw + Math.PI + 0.5);
    return 'car at ' + best.x.toFixed(0) + ',' + best.z.toFixed(0) + ' facing away from the water; launch possible ' + g.boat.canLaunch();
  })()

(async () => {
    const g = __rhf.game;
    // the HUD has caught up with the car: the pill sits in its driving place
    await __until(() => g.interaction2 && g.interaction2.label === 'LAUNCH' && document.getElementById('btn-interact2').classList.contains('driving'), 120000);
    await new Promise((r) => setTimeout(r, 1500));
    return 'second pill: ' + (g.interaction2 ? g.interaction2.label : 'none') + ', shown ' + !document.getElementById('btn-interact2').hidden;
  })()

(async () => {
    const g = __rhf.game;
    await __until(() => g.boat.where === 'water', 240000);
    const B = g.boat;
    const w = g.world.waterAt(B.pos.x, B.pos.z);
    return 'launched: where ' + B.where + ', water depth under the boat ' + (w ? w.depth.toFixed(2) : 'none') + ', boat y ' + B.pos.y.toFixed(2) + ' level ' + (w ? w.level.toFixed(2) : '-');
  })()

(() => {
    const g = __rhf.game;
    __rhf.session.exitCar(true);
    // to the water's edge next to the boat
    const B = g.boat;
    const s = B.shoreSpot();
    if (s) g.player.place(s.x, s.z, Math.atan2(-(B.pos.x - s.x), -(B.pos.z - s.z)));
    return 'on the shore ' + (s ? Math.hypot(B.pos.x - s.x, B.pos.z - s.z).toFixed(1) + ' m from the boat' : 'NO SHORE SPOT');
  })()

(async () => {
    const g = __rhf.game;
    await __until(() => g.interaction2 && g.interaction2.label === 'BOARD' && !document.getElementById('btn-interact2').classList.contains('driving'), 120000);
    await new Promise((r) => setTimeout(r, 1500));
    return 'pill: ' + (g.interaction2 ? g.interaction2.label : 'none');
  })()

(async () => {
    const g = __rhf.game;
    await __until(() => g.player.mode === 'boat', 120000);
    const B = g.boat;
    window.__start = { x: B.pos.x, z: B.pos.z };
    __rhf.hold('gas', true);
    const t0 = g.time;
    await __until(() => g.time - t0 > 4, 120000);
    __rhf.hold('gas', false);
    const w = g.world.waterAt(B.pos.x, B.pos.z);
    return 'mode ' + g.player.mode + '; after 4 s of gas: speed ' + B.speed.toFixed(1) + ' m/s, moved ' + Math.hypot(B.pos.x - __start.x, B.pos.z - __start.z).toFixed(1) + ' m, still afloat ' + !!w + ', speedo ' + document.getElementById('speedo-val').textContent + ' km/h ' + document.getElementById('speedo-gear').textContent;
  })()

(async () => {
    await __until(() => !document.getElementById('btn-cam').hidden, 120000);
    await new Promise((r) => setTimeout(r, 1500));
    return 'camera button shown';
  })()

(async () => {
    const g = __rhf.game;
    await __until(() => g.boat.camMode === 'chase', 30000);
    await new Promise((r) => setTimeout(r, 2500));
    return 'camera ' + g.boat.camMode;
  })()

(async () => {
    const g = __rhf.game;
    const W = g.world;
    const B = g.boat;
    const f = W.place('falls');
    let lip = null;
    for (let s = f.riverS - 120; s < f.riverS + 120; s += 1) {
      const d = W.riverLevel(s) - W.riverLevel(s + 2);
      if (!lip || d > lip.d) lip = { s, d };
    }
    // the deepest spot upstream of the lip
    let start = null;
    for (let s = lip.s - 40; s < lip.s - 12; s += 2) {
      const c = W.river.sample(s);
      const w = W.waterAt(c.x, c.z);
      if (w && w.depth > 0.9 && (!start || w.depth > start.w.depth)) start = { s, c, w };
    }
    if (!start) return 'no deep water above the falls';
    const t = W.river.sample(start.s + 2);
    B.pos.set(start.c.x, start.w.level, start.c.z);
    B.yaw = Math.atan2(t.x - start.c.x, t.z - start.c.z);
    B.speed = 0;
    const lvl0 = start.w.level;
    let lowest = lvl0;
    __rhf.hold('gas', true);
    const t0 = g.time;
    await __until(() => {
      const w = W.waterAt(B.pos.x, B.pos.z);
      if (w) lowest = Math.min(lowest, w.level);
      return g.time - t0 > 6;
    }, 240000);
    __rhf.hold('gas', false);
    const here = W.river.nearest(B.pos.x, B.pos.z);
    return 'falls: drop ' + lip.d.toFixed(1) + ' m at s ' + lip.s + ', boat started at s ' + start.s + ' and is now at s ' + here.s.toFixed(0) + ', lowest water under her ' + (lvl0 - lowest).toFixed(2) + ' m below the start';
  })()

(async () => {
    const g = __rhf.game;
    const B = g.boat;
    const t0 = g.time;
    await __until(() => Math.abs(B.speed) < 1.4 || g.time - t0 > 20, 120000);
    await __until(() => g.interaction && g.interaction.label === 'FISH' && document.getElementById('btn-interact').classList.contains('driving'), 120000);
    await new Promise((r) => setTimeout(r, 1500));
    return 'speed ' + B.speed.toFixed(2) + ', pill ' + (g.interaction ? g.interaction.label : 'none');
  })()

(async () => {
    const g = __rhf.game;
    await __until(() => g.player.boat, 30000);
    await new Promise((r) => setTimeout(r, 2500));
    const P = g.player;
    return 'fishing from the boat: mode ' + P.mode + ', aboard ' + !!P.boat + ', tool ' + P.tool + ', water ahead ' + g.fishing.aim.hasWater + ', primary ' + document.getElementById('btn-primary').textContent + ', pill ' + (g.interaction ? g.interaction.label : 'none') + ', bears can reach you ' + g.bears.exposed();
  })()

(async () => {
    const g = __rhf.game;
    const B = g.boat;
    B.takeHelm();
    const r = B.rear();
    const W = g.world;
    // the nearest floating spot to the trailer
    let best = null;
    for (let d = 2; d < 14 && !best; d += 1)
      for (let i = 0; i < 24; i++) {
        const a = (i / 24) * Math.PI * 2;
        const x = r.x + Math.sin(a) * d;
        const z = r.z + Math.cos(a) * d;
        const w = W.waterAt(x, z);
        if (w && w.depth > 0.8) {
          best = { x, z, w };
          break;
        }
      }
    if (!best) return 'no water near the trailer';
    B.pos.set(best.x, best.w.level, best.z);
    B.speed = 0;
    await __until(() => g.interaction2 && g.interaction2.label === 'LOAD BOAT' && document.getElementById('btn-interact2').classList.contains('driving'), 120000);
    await new Promise((r) => setTimeout(r, 1500));
    return 'near the trailer: pill ' + (g.interaction2 ? g.interaction2.label : 'none');
  })()

(async () => {
    const g = __rhf.game;
    await __until(() => g.boat.where === 'trailer', 240000);
    __rhf.session.save();
    const raw = localStorage.getItem('rubenHotrodFishing.save.v1');
    const d = JSON.parse(raw);
    return 'loaded: where ' + g.boat.where + ', player ' + g.player.mode + ', saved boat ' + JSON.stringify(d.boat) + ', car towing ' + g.hotrod.towing;
  })()
